import contextlib
import copy
import io
import json
import signal


class _CaseTimeout(Exception):
    pass


def _on_alarm(signum, frame):
    raise _CaseTimeout('candidate exceeded 5 second limit')


def _load(src):
    ns = {'__name__': 'candidate_block_9'}
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
        exec(compile(src, 'block-9.txt', 'exec'), ns)
    return ns


def main():
    try:
        with open('inputs.json', 'r', encoding='utf-8') as fh:
            cases = json.load(fh)
        with open('block-9.txt', 'r', encoding='utf-8') as fh:
            src = fh.read()
        if not isinstance(cases, list):
            raise ValueError('inputs.json must contain a list')
    except Exception as exc:
        print(json.dumps({'results': [], 'harness_error': 'setup failed: %s: %s' % (type(exc).__name__, exc)}))
        return

    use_alarm = hasattr(signal, 'SIGALRM') and hasattr(signal, 'setitimer')
    if use_alarm:
        signal.signal(signal.SIGALRM, _on_alarm)

    results = []
    for case in cases:
        cid = case.get('id') if isinstance(case, dict) else None
        try:
            args = case['input']
            if isinstance(args, dict) and 'values' in args:
                args = args['values']
            call_args = copy.deepcopy(args)
            out = io.StringIO()
            with contextlib.redirect_stdout(out), contextlib.redirect_stderr(out):
                ns = _load(src)
                fn = ns.get('average')
                if not callable(fn):
                    raise NameError('average is not defined by the candidate')
                if use_alarm:
                    signal.setitimer(signal.ITIMER_REAL, 5.0)
                try:
                    value = fn(call_args)
                finally:
                    if use_alarm:
                        signal.setitimer(signal.ITIMER_REAL, 0)
            json.dumps(value, allow_nan=False)
            results.append({'id': cid, 'actual': value})
        except Exception as exc:
            results.append({'id': cid, 'error': '%s: %s' % (type(exc).__name__, exc)})

    print(json.dumps({'results': results}, allow_nan=False))


if __name__ == '__main__':
    main()

import contextlib
import copy
import io
import json
import sys


def emit(obj):
    sys.stdout.write(json.dumps(obj, allow_nan=False) + "\n")
    sys.stdout.flush()


def load_candidate():
    with open("block-3.txt", "r", encoding="utf-8") as fh:
        src = fh.read()
    ns = {"__name__": "candidate_block3"}
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        exec(compile(src, "block-3.txt", "exec"), ns)
    fn = ns.get("calculate_average")
    if not callable(fn):
        raise RuntimeError("calculate_average is not defined by the candidate block")
    return fn


def load_cases():
    with open("inputs.json", "r", encoding="utf-8") as fh:
        cases = json.load(fh)
    if not isinstance(cases, list):
        raise ValueError("inputs.json must contain a JSON list")
    return cases


def main():
    try:
        fn = load_candidate()
    except Exception as e:
        emit({"results": [], "harness_error": "candidate load failure: " + repr(e)})
        return

    try:
        cases = load_cases()
    except Exception as e:
        emit({"results": [], "harness_error": "input load failure: " + repr(e)})
        return

    results = []
    for case in cases:
        cid = case.get("id") if isinstance(case, dict) else None
        try:
            values = case["input"]["values"]
        except Exception as e:
            results.append({"id": cid, "error": "invalid input record: " + repr(e)})
            continue

        buf = io.StringIO()
        try:
            args = copy.deepcopy(values)
            with contextlib.redirect_stdout(buf):
                value = fn(args)
            json.dumps(value, allow_nan=False)
            results.append({"id": cid, "actual": value})
        except Exception as e:
            results.append({"id": cid, "error": type(e).__name__ + ": " + str(e)})

    emit({"results": results})


if __name__ == "__main__":
    main()
